using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Notifications.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Notifications.Commands.MarkNotificationRead;public sealed class MarkNotificationReadCommandHandler(INotificationRepository repository,IApplicationDbContext db):IRequestHandler<MarkNotificationReadCommand,Result<NotificationDto>>{public async Task<Result<NotificationDto>>Handle(MarkNotificationReadCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.UserId,request.Id,cancellationToken);if(e is null)return Result.Failure<NotificationDto>(new Error("Notifications.NotFound","The notification was not found.",ErrorType.NotFound));if(request.IsRead)e.MarkAsRead();else e.MarkAsUnread();await db.SaveChangesAsync(cancellationToken);return Result.Success(NotificationDto.FromEntity(e));}}
